import os
from google.cloud import texttospeech

def select_voice(payload, config=None):
    config = config or {}
    client = texttospeech.TextToSpeechClient()
    language_code = (
        payload.get("locale")
        or payload.get("language_code")
        or config.get("locale")
        or config.get("language_code")
        or "en-US"
    )
    gender_value = payload.get("ssml_gender") or config.get("ssml_gender")
    name = payload.get("voice_name") or config.get("voice_name")

    if isinstance(gender_value, str):
        gender_map = {
            "MALE": texttospeech.SsmlVoiceGender.MALE,
            "FEMALE": texttospeech.SsmlVoiceGender.FEMALE,
            "NEUTRAL": texttospeech.SsmlVoiceGender.NEUTRAL,
            "SSML_VOICE_GENDER_UNSPECIFIED": texttospeech.SsmlVoiceGender.SSML_VOICE_GENDER_UNSPECIFIED,
        }
        ssml_gender = gender_map.get(gender_value.upper(), texttospeech.SsmlVoiceGender.SSML_VOICE_GENDER_UNSPECIFIED)
    else:
        ssml_gender = gender_value or texttospeech.SsmlVoiceGender.SSML_VOICE_GENDER_UNSPECIFIED

    response = client.list_voices(language_code=language_code)
    voices = list(response.voices)

    if name:
        exact = next((v for v in voices if v.name == name), None)
        if exact:
            selected = exact
        else:
            selected = None
    else:
        selected = None

    if selected is None and ssml_gender != texttospeech.SsmlVoiceGender.SSML_VOICE_GENDER_UNSPECIFIED:
        selected = next(
            (
                v
                for v in voices
                if v.ssml_gender == ssml_gender and language_code in getattr(v, "language_codes", [])
            ),
            None,
        )

    if selected is None:
        selected = next(
            (v for v in voices if language_code in getattr(v, "language_codes", [])),
            voices[0] if voices else None,
        )

    result = {
        "provider": "google_cloud_text_to_speech",
        "locale": language_code,
        "selected_voice": None if selected is None else {
            "name": selected.name,
            "language_codes": list(selected.language_codes),
            "ssml_gender": texttospeech.SsmlVoiceGender(selected.ssml_gender).name,
            "natural_sample_rate_hertz": selected.natural_sample_rate_hertz,
        },
        "voices": [
            {
                "name": v.name,
                "language_codes": list(v.language_codes),
                "ssml_gender": texttospeech.SsmlVoiceGender(v.ssml_gender).name,
                "natural_sample_rate_hertz": v.natural_sample_rate_hertz,
            }
            for v in voices
        ],
        "google_application_credentials": os.getenv("GOOGLE_APPLICATION_CREDENTIALS"),
    }
    return result
